```tsx
import { useId } from "react";
import "./EmptyState.css";

export interface EmptyStateProps {
  title: string;
  message: string;
  actionLabel: string;
  onAction: () => void;
}

export function EmptyState({
  title,
  message,
  actionLabel,
  onAction,
}: EmptyStateProps) {
  const headingId = useId();

  return (
    <section className="empty-state" aria-labelledby={headingId}>
      <h2 id={headingId} className="empty-state__title">
        {title}
      </h2>
      <p className="empty-state__message">{message}</p>
      <button
        type="button"
        className="empty-state__action"
        onClick={onAction}
      >
        {actionLabel}
      </button>
    </section>
  );
}
```

```css
/*
  Theme tokens. Day values are the defaults. Night values apply when the
  root element carries data-theme="night". Both sets are checked for
  WCAG AA contrast (body text >= 4.5:1, button text >= 4.5:1, focus ring >= 3:1).
*/
:root {
  --myelin-empty-surface: #f6f4ef;
  --myelin-empty-text: #1f2a27;
  --myelin-empty-text-muted: #4f5d59;
  --myelin-empty-accent: #3d6b5c;
  --myelin-empty-accent-hover: #335b4d;
  --myelin-empty-accent-text: #ffffff;
  --myelin-empty-focus: #1f5fa8;
}

:root[data-theme="night"] {
  --myelin-empty-surface: #141b1d;
  --myelin-empty-text: #e6ecea;
  --myelin-empty-text-muted: #a7b5b1;
  --myelin-empty-accent: #9bc7b4;
  --myelin-empty-accent-hover: #b2d6c6;
  --myelin-empty-accent-text: #0f1a17;
  --myelin-empty-focus: #8ab8ff;
}

.empty-state {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  width: 100%;
  min-height: 100%;
  padding: 3rem 1.5rem;
  text-align: center;
  background: var(--myelin-empty-surface);
  color: var(--myelin-empty-text);
  font-family: inherit;
}

.empty-state__title {
  margin: 0;
  font-size: 1.375rem;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: 0.01em;
  color: var(--myelin-empty-text);
}

.empty-state__message {
  margin: 0;
  max-width: 34ch;
  font-size: 1rem;
  line-height: 1.6;
  color: var(--myelin-empty-text-muted);
}

.empty-state__action {
  appearance: none;
  margin-top: 0.5rem;
  min-height: 44px;
  min-width: 44px;
  padding: 0.7rem 1.5rem;
  border: 0;
  border-radius: 999px;
  background: var(--myelin-empty-accent);
  color: var(--myelin-empty-accent-text);
  font: inherit;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 160ms ease-out, transform 160ms ease-out;
}

.empty-state__action:hover {
  background: var(--myelin-empty-accent-hover);
}

.empty-state__action:active {
  transform: translateY(1px);
}

.empty-state__action:focus {
  outline: none;
}

.empty-state__action:focus-visible {
  outline: 3px solid var(--myelin-empty-focus);
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .empty-state__action {
    transition: none;
  }
}
